"""Convert Montserrat Medium to compact 1-bpp cells for the native ST7789 UI."""
import argparse
import hashlib
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[1]
TEXT = ''.join(chr(code) for code in range(32, 127)) + '°³'
NUMBERS = '0123456789.-'
# Nominal TTF size, baseline, line height, supported characters.
FONTS = [(12, 12, 16, TEXT), (16, 15, 20, TEXT),
         (32, 30, 38, NUMBERS), (60, 55, 64, NUMBERS)]


def generate(source, output):
    lines = [
        '/* Generated by scripts/generate_industrial_fonts.py; do not edit.',
        ' * Montserrat Project Authors, SIL OFL 1.1; see licenses/industrial-OFL.txt.',
        f' * Source SHA-256: {hashlib.sha256(source.read_bytes()).hexdigest()}',
        ' * Cropped vertical bounds; row-major bits, MSB first, no row padding. */',
        '#ifndef INDUSTRIAL_FONTS_H', '#define INDUSTRIAL_FONTS_H', '',
        'typedef struct {',
        '    uint16_t offset;',
        '    uint8_t advance, top, height;',
        '} industrial_glyph_t;', '',
        'typedef struct {',
        '    const uint8_t *bitmap;',
        '    const industrial_glyph_t *glyphs;',
        '    uint8_t height;',
        '} industrial_font_t;', '',
    ]
    total = 0
    for size, baseline, height, chars in FONTS:
        font = ImageFont.truetype(str(source), size)
        bitmap, glyphs = bytearray(), []
        for char in chars:
            bounds = font.getbbox(char, anchor='ls')
            left_padding = max(-bounds[0], 0)
            advance = max(round(font.getlength(char)), bounds[2]) + left_padding
            cell = Image.new('L', (advance, height))
            ImageDraw.Draw(cell).text((left_padding, baseline), char, font=font,
                                     fill=255, anchor='ls')
            cell = cell.point(lambda value: 255 if value >= 128 else 0)
            box = cell.getbbox()
            top, bottom = (box[1], box[3]) if box else (0, 0)
            glyphs.append((len(bitmap), advance, top, bottom - top))
            bits = [cell.getpixel((x, y)) != 0
                    for y in range(top, bottom) for x in range(advance)]
            for start in range(0, len(bits), 8):
                bitmap.append(sum(int(bit) << (7 - i) for i, bit in enumerate(bits[start:start + 8])))
        lines += [f'static const uint8_t s_industrial_{size}_bitmap[] = {{']
        for start in range(0, len(bitmap), 16):
            lines.append('    ' + ', '.join(f'0x{value:02X}' for value in bitmap[start:start + 16]) + ',')
        lines += ['};', f'static const industrial_glyph_t s_industrial_{size}_glyphs[] = {{']
        lines += [f'    {{ {offset}, {advance}, {top}, {rows} }}, /* U+{ord(char):04X} */'
                  for char, (offset, advance, top, rows) in zip(chars, glyphs)]
        lines += ['};', '']
        total += len(bitmap) + len(glyphs) * 6
        print(f'{size}px: bitmap={len(bitmap)}, metrics={len(glyphs) * 6}, line={height}')
    lines += ['static const industrial_font_t s_industrial_fonts[] = {']
    for size, _, height, _ in FONTS:
        lines.append(f'    {{ s_industrial_{size}_bitmap, s_industrial_{size}_glyphs, {height} }},')
    lines += ['};', '', '#endif', '']
    output.write_text('\n'.join(lines), encoding='utf-8')
    print(f'Glyph data + metrics: {total} bytes (font descriptors excluded)')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('source', type=Path, help='Montserrat Medium TTF file')
    parser.add_argument('--output', type=Path, default=ROOT / 'OLED/industrial_fonts.h')
    args = parser.parse_args()
    generate(args.source, args.output)
